import {
  ChangeDetectionStrategy,
  Component,
  Directive,
  ElementRef,
  contentChild,
  effect,
  inject,
  input,
  model,
} from '@angular/core';

@Directive({ selector: '[aevkoHoverCardTrigger]', standalone: true })
export class AevkoHoverCardTrigger {
  readonly element = inject<ElementRef<HTMLElement>>(ElementRef);
}

@Component({
  selector: 'aevko-hover-card',
  standalone: true,
  templateUrl: './hover-card.component.html',
  styleUrl: './hover-card.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    '(mouseenter)': 'schedule(true)',
    '(mouseleave)': 'schedule(false)',
    '(focusin)': 'schedule(true)',
    '(focusout)': 'schedule(false)',
    '(keydown.escape)': 'open.set(false)',
  },
})
export class AevkoHoverCard {
  readonly id = input('aevko-hover-card');
  readonly open = model(false);
  readonly side = input<'top' | 'right' | 'bottom' | 'left'>('bottom');
  readonly align = input<'start' | 'center' | 'end'>('center');
  readonly delay = input(150);
  readonly closeDelay = input(200);
  private timer?: ReturnType<typeof setTimeout>;
  private readonly trigger = contentChild(AevkoHoverCardTrigger);
  constructor() {
    effect(() => {
      const element = this.trigger()?.element.nativeElement;
      if (!element) return;
      element.setAttribute('aria-describedby', this.id());
    });
  }
  protected schedule(value: boolean): void {
    clearTimeout(this.timer);
    this.timer = setTimeout(() => this.open.set(value), value ? this.delay() : this.closeDelay());
  }
}

:host {
  display: inline-block;
  position: relative;
}
aside {
  background: var(--aevko-surface, #fff);
  border: 1px solid var(--aevko-border, #d4d4d4);
  border-radius: 0;
  box-shadow: 0 12px 30px rgb(0 0 0 / 0.12);
  color: var(--aevko-foreground, #171717);
  inline-size: min(20rem, calc(100vw - 2rem));
  padding: 1rem;
  position: absolute;
  z-index: 30;
}
aside[data-side='bottom'] {
  inset-block-start: calc(100% + 0.5rem);
}
aside[data-side='top'] {
  inset-block-end: calc(100% + 0.5rem);
}
aside[data-side='right'] {
  inset-inline-start: calc(100% + 0.5rem);
  inset-block-start: 0;
}
aside[data-side='left'] {
  inset-inline-end: calc(100% + 0.5rem);
  inset-block-start: 0;
}
aside[data-align='start'] {
  inset-inline-start: 0;
}
aside[data-align='center'] {
  inset-inline-start: 50%;
  transform: translateX(-50%);
}
aside[data-align='end'] {
  inset-inline-end: 0;
}
aside[data-side='left'],
aside[data-side='right'] {
  transform: none;
}
@media (prefers-color-scheme: dark) {
  aside {
    --aevko-surface: #171717;
    --aevko-foreground: #f5f5f5;
    --aevko-border: #404040;
  }
}
